// src/app/stock/[symbol]/FundamentalTab.jsx
// Why: Render fundamental analysis markdown generated by Gemini API in a dark modern card wrapper with ErrorBoundary & Skeleton resilience.
'use client';

import React, { useState, useEffect } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { BankIcon } from '../../../components/ui/Icons';
import { AISummarySkeleton } from '../../../components/ui/Skeleton';
import ErrorBoundary from '../../../components/ui/ErrorBoundary';

function FundamentalTabContent({ symbol }) {
  const [markdown, setMarkdown] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchMarkdown = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/fundamental?symbol=${symbol}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || '無法載入基本面分析數據');
      setMarkdown(json.markdown);
    } catch (err) {
      console.error('Error loading fundamental markdown:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMarkdown();
  }, [symbol]);

  if (loading) {
    return (
      <AISummarySkeleton 
        title={`Gemini 華爾街資深分析師正為您生成 ${symbol} 完整基本面報告…`} 
      />
    );
  }

  if (error) {
    return (
      <div className="border border-red-900/50 bg-red-950/20 rounded-2xl p-8 text-center backdrop-blur-sm">
        <h3 className="text-lg font-bold text-red-400 mb-2">基本面分析載入失敗</h3>
        <p className="text-sm text-slate-400 mb-4">{error}</p>
        <button
          type="button"
          onClick={fetchMarkdown}
          className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-semibold bg-cyan-500/15 hover:bg-cyan-500/25 text-cyan-300 border border-cyan-500/30 transition-all cursor-pointer"
        >
          重新載入
        </button>
      </div>
    );
  }

  return (
    <div className="border border-slate-800/80 bg-[#0B0F19]/80 rounded-2xl p-6 sm:p-8 backdrop-blur-sm shadow-xl">
      <div className="flex items-center justify-between border-b border-slate-800/80 pb-4 mb-6">
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-xl bg-cyan-950/60 border border-cyan-800/40 text-cyan-400 shadow-sm">
            <BankIcon className="w-5 h-5" />
          </div>
          <div>
            <h2 className="text-lg font-bold text-slate-100">{symbol} 華爾街資深基本面報告</h2>
            <p className="text-xs text-slate-400">由 Google Gemini 結合即時網路檢索分析生成</p>
          </div>
        </div>
        <span className="px-3 py-1 text-xs font-semibold rounded-full bg-cyan-500/10 text-cyan-400 border border-cyan-500/30">
          AI 深度報告
        </span>
      </div>

      <div className="prose prose-invert max-w-none text-slate-200 text-sm leading-relaxed space-y-4">
        <ReactMarkdown remarkPlugins={[remarkGfm]}>{markdown}</ReactMarkdown>
      </div>
    </div>
  );
}

export default function FundamentalTab(props) {
  return (
    <ErrorBoundary
      fallbackTitle={`${props.symbol || ''} 基本面分析載入異常`}
      fallbackMessage="基本面分析視圖渲染時發生錯誤，請點擊下方按鈕重新載入。"
      resetKeys={[props.symbol]}
    >
      <FundamentalTabContent {...props} />
    </ErrorBoundary>
  );
}
